code.css:
*,*::before,*::after{box-sizing:border-box}
body{margin:0;background:#f8f2e7;color:#2f211a;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Hiragino Sans GB","Microsoft YaHei","Noto Sans CJK SC",sans-serif;font-size:17px;line-height:1.65}
img{display:block;max-width:100%;height:auto}
a{color:#8a3120;text-decoration:underline;text-underline-offset:3px}
a:hover{color:#6f2417}
a:focus-visible{outline:3px solid #a63e28;outline-offset:2px}
.wrap{width:100%;max-width:1080px;margin:0 auto;padding:0 20px}
h1,h2,h3{margin:0;font-weight:800;color:#2f211a}
h1{font-size:clamp(2rem,5vw,2.9rem);line-height:1.18}
h2{font-size:clamp(1.3rem,2.4vw,1.6rem);line-height:1.3;margin-bottom:18px}
h3{font-size:1.2rem;line-height:1.4}
p{margin:0 0 14px}
p:last-child{margin-bottom:0}
.prose{max-width:36em}
.site-header{background:#f8f2e7;border-bottom:3px solid #2f211a}
.header-inner{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:58px;padding-top:9px;padding-bottom:9px}
.brand{font-size:1.25rem;font-weight:800;color:#a63e28;text-decoration:none;letter-spacing:0.08em;white-space:nowrap}
.brand:hover{color:#8a3120}
.site-nav{display:flex;gap:18px;font-size:0.95rem}
.site-nav a{color:#2f211a;text-decoration:none;padding:4px 0;border-bottom:2px solid transparent}
.site-nav a:hover{border-bottom-color:#a63e28;color:#2f211a}
.hero{padding:58px 0 50px;border-bottom:1px solid #e0d0ba}
.hero h1{color:#a63e28}
.hero-sub{font-size:1.12rem;max-width:30em;margin:16px 0 26px}
.btn-primary{display:inline-block;background:#a63e28;color:#fdf7ee;text-decoration:none;font-weight:800;padding:12px 26px;border-radius:2px;letter-spacing:0.04em}
.btn-primary:hover{background:#8a3120;color:#fdf7ee}
.page-head{padding:48px 0 36px;border-bottom:1px solid #e0d0ba}
.lede{font-size:1.08rem;color:#3d2c20;max-width:34em;margin:14px 0 0}
.lede-sub{font-size:0.95rem;color:#4a3627;max-width:40em;margin:10px 0 0}
.band{padding:52px 0;border-bottom:1px solid #e6d9c6}
.band-warm{background:#f1e5d3}
.band-dark{background:#2f211a;color:#f8f2e7}
.band-dark h2{color:#f8f2e7}
.band-dark p{color:#f0e6d8}
.band-dark a{color:#f3d3bd}
.band-dark a:hover{color:#fdf7ee}
.band-note{margin:0;font-size:0.95rem;color:#e4d7c6}
.situations{padding:52px 0;border-bottom:1px solid #e6d9c6}
.situation-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:44px;align-items:start}
.situation h3{color:#a63e28;margin-bottom:10px}
.situation p{color:#3d2c20}
.situation-main{padding-left:18px;border-left:4px solid #a63e28}
.after-note{margin:28px 0 0;font-size:0.95rem;color:#3d2c20;max-width:44em}
.hours-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 44px;margin:0 0 18px;padding:0}
.hours-list div{display:flex;gap:14px;align-items:baseline;padding:12px 0;border-top:1px solid #4d3a2e}
.hours-list dt{flex:0 0 5.5em;font-size:0.9rem;font-weight:700;color:#cbb9a6}
.hours-list dd{margin:0;font-weight:700;color:#f8f2e7;font-variant-numeric:tabular-nums}
.timeline{list-style:none;margin:0;padding:0;max-width:42em}
.timeline li{display:flex;gap:20px;align-items:baseline;padding:12px 0;border-top:1px solid #e6d9c6}
.timeline li:last-child{border-bottom:1px solid #e6d9c6}
.timeline .year{flex:0 0 4.5em;font-weight:800;color:#a63e28;font-size:1.05rem;font-variant-numeric:tabular-nums}
.timeline .event{flex:1 1 auto;min-width:0}
.news{list-style:none;margin:0;padding:0}
.news li{display:grid;grid-template-columns:7.5em minmax(0,1fr);gap:18px;align-items:baseline;padding:14px 0;border-top:1px solid #e6d9c6}
.news li:last-child{border-bottom:1px solid #e6d9c6}
.news .date{font-weight:800;color:#8a3120;font-size:0.95rem;font-variant-numeric:tabular-nums}
.news p{margin:0;color:#3d2c20;max-width:40em}
.dish{border-top:1px solid #dccdb8;padding:22px 0}
.dish:last-child{border-bottom:1px solid #dccdb8}
.band-warm .dish{border-top-color:#d8c3a8}
.band-warm .dish:last-child{border-bottom-color:#d8c3a8}
.dish-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap}
.dish-head h3{font-size:1.25rem}
.dish-price{margin:0;font-weight:800;color:#a63e28;white-space:nowrap;font-variant-numeric:tabular-nums}
.dish-price .num{font-size:1.5rem;line-height:1}
.dish-rice{margin:6px 0 0;font-size:0.9rem;font-weight:700;color:#8a3120}
.dish-desc{margin:10px 0 0;max-width:38em}
.dish-meta{margin:6px 0 0;max-width:38em;font-size:0.95rem;color:#4a3627}
.dish-note{margin:10px 0 0;padding-left:12px;border-left:3px solid #dccdb8;max-width:34em;font-size:0.95rem;color:#3d2c20}
.extra-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:44px;align-items:start}
.ingredient-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px;margin-top:26px}
.ingredient-grid figure{margin:0}
.ingredient-grid figcaption{margin-top:10px;font-size:0.93rem;color:#3d2c20;line-height:1.6}
.ing-name{display:block;font-weight:800;color:#a63e28;font-size:1.05rem;margin-bottom:2px}
.disclaim{display:block;margin-top:4px;color:#5a4638;font-size:0.88rem}
.steps{margin:0;padding-left:1.5em;max-width:40em}
.steps li{padding:9px 0;border-top:1px solid #d8c3a8}
.steps li:last-child{border-bottom:1px solid #d8c3a8}
.steps li::marker{color:#a63e28;font-weight:800}
.hours-table{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 44px;margin:0 0 18px}
.hours-table div{border-top:3px solid #2f211a;padding-top:10px}
.hours-table dt{margin:0 0 4px;font-size:0.9rem;font-weight:800;color:#8a3120}
.hours-table dd{margin:0;display:flex;flex-direction:column;gap:2px}
.hours-table strong{font-size:1.55rem;font-weight:800;line-height:1.2;font-variant-numeric:tabular-nums}
.hours-table span{font-size:0.93rem;color:#4a3627}
.two-col{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:44px;align-items:start}
.gap-list{display:grid;gap:10px;margin:0}
.gap-list div{border-bottom:1px solid #e0d0ba;padding-bottom:8px}
.gap-list dt{font-size:0.88rem;font-weight:700;color:#5a4638}
.gap-list dd{margin:2px 0 0;font-weight:700}
.refusal{background:#2f211a;padding:20px 22px;border-radius:2px;margin:18px 0}
.refusal p{margin:0;color:#f8f2e7;font-weight:800;font-size:1.05rem;max-width:40em}
.qa{margin:0;padding:0}
.qa div{padding:14px 0;border-top:1px solid #e0d0ba}
.qa div:last-child{border-bottom:1px solid #e0d0ba}
.qa dt{font-weight:800;margin-bottom:4px}
.qa dd{margin:0;color:#4a3627;max-width:40em}
.site-footer{background:#2f211a;color:#f8f2e7;padding:40px 0 44px}
.footer-inner{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:34px;align-items:start}
.footer-name{margin:0 0 8px;color:#f8f2e7;font-size:1.15rem;font-weight:800;letter-spacing:0.08em}
.site-footer p{margin:0;color:#e8ddcd;font-size:0.95rem;max-width:30em}
.footer-info{margin:0;display:grid;gap:10px;font-size:0.92rem}
.footer-info dt{color:#cbb9a6;font-size:0.85rem;font-weight:700}
.footer-info dd{margin:0;color:#f0e6d8;word-break:break-word}
@media (max-width:768px){
  body{font-size:16.5px}
  .hero{padding:40px 0 34px}
  .page-head{padding:34px 0 28px}
  .band{padding:30px 0}
  .situations{padding:30px 0}
  .situation-grid,.extra-grid,.two-col,.footer-inner,.ingredient-grid{grid-template-columns:minmax(0,1fr);gap:26px}
  .situation-main{padding-left:14px}
  .news li{grid-template-columns:minmax(0,1fr);gap:4px}
  .hours-list{grid-template-columns:minmax(0,1fr)}
  .hours-table{grid-template-columns:minmax(0,1fr);gap:16px}
  .hours-table strong{font-size:1.35rem}
}
